eda.sys_Dialog.showInputDialog(
  '请输入铺铜间距',               // 输入框上方文字
  '输入 1～100 之间的整数（单位 mil）', // 输入框下方文字
  '铺铜设置',                     // 窗口标题
  'number',                       // 输入类型（同 HTML input 的 type）
  5,                              // 默认值
  { min: 1, max: 100, step: 1 },  // 其它输入属性（min、max、step 等）
  (value) => {
    console.log('用户输入的间距：', value);
  }
);
